class Solution {
public:
    int countBlocks(BigArray* nums) {
        long long n = nums->size(), i = 0;
        int blocks = 0;
        while (i < n) {
            int value = nums->at(i);
            long long lo = i + 1, hi = n;
            while (lo < hi) {
                long long mid = lo + (hi - lo) / 2;
                if (nums->at(mid) == value) lo = mid + 1;
                else hi = mid;
            }
            i = lo;
            ++blocks;
        }
        return blocks;
    }
};
